const j = $input.first().json || {};
const backendBase = String(j.backendBase || 'http://127.0.0.1:5050').replace(/\/+$/, '');
const apiHubBase = String(j.apiHubBase || 'http://127.0.0.1:4321').replace(/\/+$/, '');
const productName = String(j.productName || '').trim();
const imageUrl = String(j.imageUrl || '').trim();
if (!productName) throw new Error('G0: productName 필수');
if (!imageUrl) throw new Error('G0: imageUrl 필수');
return [{
  json: {
    backendBase,
    apiHubBase,
    productName,
    imageUrl,
    query: productName,
    autoApplyTopDb: String(j.autoApplyTopDb || 'false') === 'true',
    project_id: '',
    sinhwaCandidates: [],
    cafe24Candidates: [],
    confirmedSinhwa: null,
    confirmedCafe24: null,
    missingFields: [],
    productFields: {},
    vmCandidates: [],
    selectedVmIndexes: [],
    generatedNote: '',
    selectedAssetNote: '',
    publishApproved: false,
    stage: 'g0-input',
    bus: 'factory-hitl-v1'
  }
}];

const bus = $('G0 Normalize Bus').first().json;
const health = $input.first().json || {};
if (health.ready === false) throw new Error('Health gate 실패: ' + (health.message || ''));
return [{ json: { ...bus, health, stage: 'g0-health-ok' } }];

const bus = $('After Health').first().json;
const child = $input.first().json || {};
const project_id = child.project_id || child.projectId || '';
if (!project_id) throw new Error('02 Analyze 후 project_id 없음');
return [{
  json: {
    ...bus,
    ...child,
    project_id,
    analysis: child.analysis || child.product_analysis || bus.analysis || null,
    stage: 'g0-analyzed'
  }
}];

const bus = $('After Analyze').first().json;
const form = $input.first().json || {};
const productName = String(form.confirmedProductName || bus.productName || '').trim();
if (!productName) throw new Error('확정 제품명 비어 있음');
return [{ json: { ...bus, productName, query: productName, stage: 'g1-ready' } }];

const bus = $('Apply G0 Name').first().json;
const child = $input.first().json || {};
function listFrom(x) {
  if (Array.isArray(x)) return x;
  if (Array.isArray(x?.sinhwaTop)) return x.sinhwaTop;
  if (Array.isArray(x?.products)) return x.products;
  return [];
}
const sinhwa = listFrom(child.sinhwaTop || child.sinhwaCandidates || child);
const cafe = Array.isArray(child.cafe24Top) ? child.cafe24Top : (Array.isArray(child.cafe24Candidates) ? child.cafe24Candidates : []);
const sinhwaLines = (sinhwa.length ? sinhwa : [{ name: '(후보 없음)', code: '' }]).slice(0, 15).map((p, i) => `${i}: ${p.name || p.product_name || p.jname || ''} | ${p.code || p.jcode || p.product_code || ''}`).join('\n');
const cafeLines = (cafe.length ? cafe : [{ name: '(후보 없음)', product_no: '' }]).slice(0, 15).map((p, i) => `${i}: ${p.name || p.product_name || ''} | no=${p.product_no || p.productNo || ''} | ${p.product_code || p.productCode || ''}`).join('\n');
return [{
  json: {
    ...bus,
    sinhwaCandidates: sinhwa,
    cafe24Candidates: cafe,
    sinhwaCount: sinhwa.length,
    cafe24Count: cafe.length,
    sinhwaPickList: sinhwaLines,
    cafe24PickList: cafeLines,
    dbChild: child,
    stage: 'g1-candidates'
  }
}];

const bus = $input.first().json;
const s = bus.sinhwaCandidates?.[0] || null;
const c = bus.cafe24Candidates?.[0] || null;
return [{ json: { ...bus, confirmedSinhwa: s, confirmedCafe24: c, sinhwaIndex: 0, cafe24Index: 0, stage: 'g1-auto-applied' } }];

const bus = $('Prep G1 Candidate Lists').first().json;
const form = $input.first().json || {};
const si = Number(form.sinhwaIndex);
const ci = Number(form.cafe24Index);
const s = Number.isFinite(si) && si >= 0 ? (bus.sinhwaCandidates[si] || null) : null;
const c = Number.isFinite(ci) && ci >= 0 ? (bus.cafe24Candidates[ci] || null) : null;
if (!s && !c) throw new Error('G1: 신화사/Cafe24 중 최소 1개 후보를 선택하세요 (앱도 확정 없이 진행 불가에 가깝음)');
return [{ json: { ...bus, confirmedSinhwa: s, confirmedCafe24: c, sinhwaIndex: si, cafe24Index: ci, stage: 'g1-confirmed' } }];

const bus = $input.first().json;
const analysis = bus.analysis || {};
const fields = {
  productName: bus.productName || analysis.product_name || '',
  category: analysis.category || '',
  material: (analysis.materials && analysis.materials[0]) || analysis.material || '',
  width_mm: analysis.width_mm || analysis.size_width || '',
  height_mm: analysis.height_mm || analysis.size_height || '',
  weight_g: analysis.weight_g || '',
  price: analysis.price_range_estimate || '',
  origin: analysis.origin || '대한민국',
};
const required = ['productName', 'category', 'material', 'width_mm', 'height_mm'];
const missingFields = required.filter(k => !String(fields[k] || '').trim());
const missingText = missingFields.length ? missingFields.join(', ') : '(없음)';
return [{
  json: {
    ...bus,
    productFields: { ...fields, ...(bus.productFields || {}) },
    missingFields,
    missingText,
    stage: 'g2-check'
  }
}];

const bus = $('G2 Check Required Fields').first().json;
const form = $input.first().json || {};
const productFields = { ...bus.productFields };
for (const k of ['category','material','width_mm','height_mm','weight_g','price','origin']) {
  if (form[k] != null && String(form[k]).trim() !== '') productFields[k] = String(form[k]).trim();
}
const required = ['productName', 'category', 'material', 'width_mm', 'height_mm'];
const missingFields = required.filter(k => !String(productFields[k] || '').trim());
if (missingFields.length) {
  throw new Error('G2 여전히 누락: ' + missingFields.join(', ') + ' — 워크플로 재실행 또는 값 보충 필요');
}
return [{ json: { ...bus, productFields, missingFields: [], stage: 'g2-filled' } }];

function pick(name) { try { return $(name).first().json; } catch (e) { return null; } }
const prev = pick('Apply G2 Fields') || pick('G2 Already Complete') || {};
const child = $input.first().json || {};
let list = [];
if (Array.isArray(child.competitor_data?.similar_products)) list = child.competitor_data.similar_products;
else if (Array.isArray(child.similar_products)) list = child.similar_products;
else if (Array.isArray(child.competitors)) list = child.competitors;
else if (Array.isArray(child.vmCandidates)) list = child.vmCandidates;
const lines = (list.length ? list : [{ title: '(후보 없음 — 직접 인덱스 -1)', url: '' }]).slice(0, 20).map((p, i) => {
  const title = p.title || p.name || p.product_name || '';
  const url = p.product_url || p.url || p.link || '';
  const platform = p.platform || p.mall || p.site || '';
  return `${i}: [${platform}] ${title} | ${url}`;
}).join('\n');
return [{
  json: {
    ...prev,
    vmCandidates: list,
    vmPickList: lines,
    competitorRaw: child,
    stage: 'g3-candidates'
  }
}];

